import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"مبدأ إعادة المعرفة فقط","description":"","frontmatter":{},"headers":[],"relativePath":"ar/87-仅回传知识原则.md","filePath":"ar/87-仅回传知识原则.md"}'),o={name:"ar/87-仅回传知识原则.md"};function l(i,t,h,n,s,p){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="مبدأ-إعادة-المعرفة-فقط" tabindex="-1">مبدأ إعادة المعرفة فقط <a class="header-anchor" href="#مبدأ-إعادة-المعرفة-فقط" aria-label="Permalink to &quot;مبدأ إعادة المعرفة فقط&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>87</td></tr><tr><td>الوحدة</td><td>التفاعل عبر الأبعاد وقواعد الزمن</td></tr><tr><td>الكلمات المفتاحية</td><td>إعادة المعرفة فقط، تنقية المعلومات، حظر إعادة المواد، ترميز المعرفة، تدقيق الإعادة</td></tr></tbody></table><h2 id="أولاً-الخلفية-التشريعية-للمبدأ-وفكرته-الجوهرية" tabindex="-1">أولاً: الخلفية التشريعية للمبدأ وفكرته الجوهرية <a class="header-anchor" href="#أولاً-الخلفية-التشريعية-للمبدأ-وفكرته-الجوهرية" aria-label="Permalink to &quot;أولاً: الخلفية التشريعية للمبدأ وفكرته الجوهرية&quot;">​</a></h2><p>مبدأ «إعادة المعرفة فقط» أحد المبادئ الأساسية في علم الآثار عبر الأبعاد وعلم آثار الارتداد الزمني لحضارة التكافل المرساة، ويعود أصله القانوني إلى المادة 48 من الدستور التكافلي: «لا يجوز إدخال أي مواد أو طاقات أو كائنات حية مكتسبة من أبعاد أخرى أو أزمنة أخرى إلى البُعد الخاص دون إذن خاص؛ ولا يقتصر الناتج المشروع للأنشطة الأثرية على المعرفة والمعلومات المجردة.» إقرار هذا المبدأ خيار مؤسسي اتخذه كون هنغ يوان بعد استخلاص دروس مؤلمة من الاستكشاف المبكر عبر الأبعاد.</p><p>في بداية تأسيس حضارة التكافل المرساة، كان الاستكشاف عبر الأبعاد ما يزال في حالة فوضى. عاد بعض المستكشفين إلى البُعد الخاص بعينات مادية وبلورات طاقة وحتى كائنات حية من أبعاد أخرى للدراسة، ما أطلق عدة «حوادث تلوث عبر الأبعاد» خطيرة. أشهر الحالات «حادثة البلورة الغريبة» — بلورة طاقة جُلبت من بُعد تجلي الطاقة، وبسبب عدم توافق متغيرات قوانينها مع البُعد الخاص، أطلقت في شبكة قوانين البُعد الخاص اضطراب قوانين استمر ثلاث سنوات، ما أدى إلى شذوذ في أنظمة الزراعة لثلاثة نطاقات نجمية وإصابة عشرات الآلاف من الزرّاع بأضرار متفاوتة. أظهرت التحقيقات اللاحقة أنه لو جرى اتباع مبدأ «إعادة المعرفة فقط» حينها، لأمكن تجنب هذه الكارثة تماماً.</p><p>الفكرة الجوهرية لمبدأ «إعادة المعرفة فقط»: المعرفة هي الوسيط الآمن الوحيد في التبادل بين الحضارات. تحمل المادة والطاقة معلومات قوانين بُعدها المصدر، وقد تطلق تفاعلات غير متوقعة بعد دخول بيئة قوانين مختلفة؛ أما المعرفة بوصفها معلومات مجردة، فبعد ترميز وتنقية مناسبتين يمكن نزع بصمات قوانين بُعدها المصدر، فتصبح مورداً آمناً مشتركاً بين الأبعاد.</p><h2 id="ثانياً-تحديد-«المعرفة»-وتصنيفها" tabindex="-1">ثانياً: تحديد «المعرفة» وتصنيفها <a class="header-anchor" href="#ثانياً-تحديد-«المعرفة»-وتصنيفها" aria-label="Permalink to &quot;ثانياً: تحديد «المعرفة» وتصنيفها&quot;">​</a></h2><p>في الإطار القانوني لمبدأ «إعادة المعرفة فقط»، للمعرفة تعريف وتصنيف صارمان. لا يمكن اعتبار كل المعلومات «معرفة» تُعاد بحرية — فقط المعلومات المجردة التي خضعت لمعاملة «تنقية المعلومات» وتأكد أنها لا تحمل أي تلوث قوانين تستوفي معيار الإعادة.</p><p>تنقسم المعرفة إلى ثلاث فئات بحسب درجة تجريدها ومستوى أمانها:</p><table tabindex="0"><thead><tr><th>فئة المعرفة</th><th>التعريف</th><th>مستوى الأمان</th><th>شرط الإعادة</th></tr></thead><tbody><tr><td>معرفة من المستوى الأول (معرفة مجردة خالصة)</td><td>مفاهيم مجردة ونظريات رياضية واستدلالات منطقية وأفكار فلسفية منفصلة تماماً عن الحوامل المادية</td><td>الأعلى (أخضر)</td><td>يمكن إعادتها مباشرة دون موافقة خاصة</td></tr><tr><td>معرفة من المستوى الثاني (معرفة وصفية)</td><td>معلومات وصفية عن الأشياء الموضوعية، تشمل السجلات التاريخية والبيانات الجغرافية والخصائص البيولوجية والأوصاف الثقافية</td><td>متوسط (أصفر)</td><td>يجب أن تخضع لمعاملة تنقية المعلومات، وتُعاد بعد موافقة إدارة الأبعاد</td></tr><tr><td>معرفة من المستوى الثالث (معرفة تقنية)</td><td>معرفة عملية تتضمن معايير تقنية محددة ومخططات هندسية وأساليب زراعة</td><td>أدنى (برتقالي)</td><td>يجب أن تخضع لتنقية معلومات صارمة وتقييم أمني، وتُعاد بعد موافقة خاصة من المجلس التشريعي للمرساة</td></tr></tbody></table><p>المحتويات التالية لا تدخل في فئة «المعرفة» ويُحظر إعادتها حظراً صارماً: العينات المادية بأي شكل (بما فيها الأحياء الدقيقة والخلايا وشظايا الجينات)، والبلورات الطاقية أو أجهزة تخزين الطاقة بأي شكل، والكائنات الحية أو الكيانات الواعية ذات الوعي الذاتي، والبيانات الخام بأي شكل لم تخضع لتنقية المعلومات، وأي تفاصيل تقنية يمكن استخدامها في الزراعة الافتراسية.</p><h2 id="ثالثاً-تقنية-تنقية-المعلومات" tabindex="-1">ثالثاً: تقنية تنقية المعلومات <a class="header-anchor" href="#ثالثاً-تقنية-تنقية-المعلومات" aria-label="Permalink to &quot;ثالثاً: تقنية تنقية المعلومات&quot;">​</a></h2><p>تنقية المعلومات الحلقة التقنية المفتاحية لضمان أمان المعرفة المُعادة. هدفها الجوهري نزع بصمات قوانين البُعد المصدر المحمولة في المعلومات الخام نزعاً تاماً، والإبقاء على المحتوى الدلالي الخالص فقط. تنقسم عملية تنقية المعلومات إلى أربع خطوات:</p><h3 id="_3-1-تفكيك-المعلومات" tabindex="-1">3.1 تفكيك المعلومات <a class="header-anchor" href="#_3-1-تفكيك-المعلومات" aria-label="Permalink to &quot;3.1 تفكيك المعلومات&quot;">​</a></h3><p>أولاً، تُفكك المعلومات الخام المراد إعادتها تفكيكاً بنيوياً، وتنقسم إلى جزأين: «المحتوى الدلالي» و«بصمة الحامل». المحتوى الدلالي هو المعنى المجرد الذي تعبر عنه المعلومات؛ وبصمة الحامل هي متغيرات قوانين البُعد المصدر التي امتصتها المعلومات أثناء التخزين والنقل. يتم التفكيك عبر «خوارزمية فصل الدلالة عن الحامل»، القادرة على تمييز المكونات الدلالية ومكونات القوانين في المعلومات وفصلها.</p><h3 id="_3-2-نزع-القوانين" tabindex="-1">3.2 نزع القوانين <a class="header-anchor" href="#_3-2-نزع-القوانين" aria-label="Permalink to &quot;3.2 نزع القوانين&quot;">​</a></h3><p>يُجرى نزع قوانين تام على بصمة الحامل المنفصلة. طريقة النزع تمرير المعلومات عبر «قناة تحييد القوانين» — قناة نقل خاصة ضُبطت متغيرات قوانينها لتكون محايدة تماماً؛ فعند مرور المعلومات، تمتص جدران القناة جميع متغيرات القوانين غير المحايدة التي تحملها. بعد نزع القوانين، لا تحمل المعلومات أي بصمات قوانين من البُعد المصدر.</p><h3 id="_3-3-إعادة-البناء-الدلالي" tabindex="-1">3.3 إعادة البناء الدلالي <a class="header-anchor" href="#_3-3-إعادة-البناء-الدلالي" aria-label="Permalink to &quot;3.3 إعادة البناء الدلالي&quot;">​</a></h3><p>على أساس نزع القوانين، يُعاد ترميز المحتوى الدلالي، وتُعاد بناء المعلومات باستخدام نظام ترميز المعلومات القياسي للبُعد الخاص. تضمن إعادة البناء الدلالي قراءة المعرفة المُعادة وفهمها بشكل صحيح في بيئة قوانين البُعد الخاص، كما تقضي إضافياً على أي بنى معلوماتية للبُعد المصدر قد تبقى.</p><h3 id="_3-4-الفحص-الأمني" tabindex="-1">3.4 الفحص الأمني <a class="header-anchor" href="#_3-4-الفحص-الأمني" aria-label="Permalink to &quot;3.4 الفحص الأمني&quot;">​</a></h3><p>يجب أن تخضع المعلومات المنقاة لفحص أمني صارم، يشمل: فحص بقايا القوانين (التأكد من أن المعلومات لا تحمل أي متغيرات قوانين غريبة)، وفحص السلامة الدلالية (التأكد من أن عملية التنقية لم تغير المحتوى الدلالي للمعلومات)، وتقييم المخاطر المحتملة (تقييم الآثار الاجتماعية والأمنية التي قد تجلبها المعرفة عند انتشارها في البُعد الخاص). فقط المعلومات التي تجتاز الفحوص الثلاثة كلها يُسمح بإعادتها.</p><h2 id="رابعاً-إجراءات-الإعادة-ونظام-التدقيق" tabindex="-1">رابعاً: إجراءات الإعادة ونظام التدقيق <a class="header-anchor" href="#رابعاً-إجراءات-الإعادة-ونظام-التدقيق" aria-label="Permalink to &quot;رابعاً: إجراءات الإعادة ونظام التدقيق&quot;">​</a></h2><p>تتبع إعادة المعرفة إدارة إجرائية صارمة. تشمل عملية إعادة كاملة الحلقات التالية:</p><ol><li><strong>تنظيم المعرفة</strong>: ينظم الفريق الأثري نتائج البحث في وثائق معرفة موحدة، مع بيان فئة المعرفة وملخص المحتوى بوضوح.</li><li><strong>طلب التنقية</strong>: تقديم طلب تنقية المعرفة وإعادتها إلى إدارة الأبعاد أو لجنة قوانين الزمن، مرفقاً به وثائق المعرفة ووثائق إذن المهمة الأثرية.</li><li><strong>تنقية المعلومات</strong>: يقوم فريق تقني متخصص بتنقية المعلومات بمعالجة التنقية الرباعية الخطوات على وثائق المعرفة.</li><li><strong>الفحص الأمني</strong>: تخضع المعرفة المنقاة للفحوص الثلاثة من مؤسسة فحص أمني مستقلة.</li><li><strong>الإعادة المصرح بها</strong>: بعد اجتياز الفحوص، توقع مؤسسة الموافقة إذن الإعادة، وتُعاد المعرفة إلى قاعدة معرفة البُعد الخاص عبر القناة المشفرة لشبكة المرساة.</li><li><strong>الأرشفة في القاعدة</strong>: بعد تدقيق قاعدة معرفة البُعد الخاص، تُسجل المعرفة المُعادة رسمياً في القاعدة، وتُفتح للباحثين الحاصلين على الصلاحيات المناسبة.</li></ol><p>يجب أن تخضع جميع عمليات الإعادة لـ«تدقيق الإعادة». يشمل محتوى التدقيق: مشروعية مصدر المعرفة المُعادة، ومعيارية عملية التنقية، واكتمال الفحص الأمني، وامتثال إجراءات الموافقة. يتولى التدقيق مكتب تدقيق إعادة المعرفة التابع للجنة الرقابة للمرساة، الذي يجري كل ثلاثة أشهر فحوصاً عشوائية على جميع عمليات الإعادة في ذلك الربع، وتدقيقاً شاملاً كل عام. تُرفع نتائج التدقيق إلى المجلس التشريعي للمرساة، ويُنشر الملخص للجمهور.</p><h2 id="خامساً-المخالفات-والمسؤولية-القانونية" tabindex="-1">خامساً: المخالفات والمسؤولية القانونية <a class="header-anchor" href="#خامساً-المخالفات-والمسؤولية-القانونية" aria-label="Permalink to &quot;خامساً: المخالفات والمسؤولية القانونية&quot;">​</a></h2><p>تشمل السلوكيات المخالفة لمبدأ «إعادة المعرفة فقط»: إعادة معلومات غير منقاة دون إذن، وتنكر عينات مادية بوصفها معرفة لإعادتها، وإخفاء بصمات قوانين البُعد المصدر عمداً في المعرفة المُعادة، ومساعدة الآخرين على إعادة غير قانونية.</p><p>وفق الدستور التكافلي وقانون إدارة التفاعلات عبر الأبعاد، تشمل المسؤولية القانونية لسلوكيات الإعادة غير القانونية: مصادرة الأشياء والمعلومات المُعادة بشكل غير قانوني، وتعليق أو إلغاء مؤهلات الطرف الأثرية والعبورية، وغرامات تزيد على 10 أضعاف قيمة الأشياء المُعادة بشكل غير قانوني، والسجن في الحالات الخطيرة، وتحمّل جميع تكاليف الإصلاح ومسؤولية التعويض في الحالات المسببة لتلوث قوانين أو ضرر إيكولوجي.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>مبدأ «إعادة المعرفة فقط» هو خط حكمة حضارة التكافل المرساة في مجال التفاعل عبر الأبعاد. بتعريفات صارمة وتقنية تنقية ناضجة وإجراءات إعادة موحدة ومسؤولية قانونية صارمة، يبني «جدار حماية أمني للمعرفة» متيناً. لا تكمن أهمية هذا المبدأ في منع التلوث على المستوى المادي فحسب، بل قبل ذلك في ترسيخ أخلاقيات التبادل بين الحضارات — التفاعل بين الحضارات يجب أن يكون محوره تصادم الأفكار، لا نهبه المادية.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>84-考古协议总纲 (البروتوكول العام لعلم الآثار)</li><li>88-跨位面伦理准则 (المعايير الأخلاقية عبر الأبعاد)</li><li>66-跨位面通讯技术 (تقنية الاتصالات عبر الأبعاد)</li></ul>',32)])])}const b=a(o,[["render",l]]);export{c as __pageData,b as default};
